import{_ as a,c as r,o as t,ag as i}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"EventEmitter, Buffers, and Streams — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/module-03-events-buffers-streams.md","filePath":"practice/node-js/module-03-events-buffers-streams.md"}'),n={name:"practice/node-js/module-03-events-buffers-streams.md"};function s(o,e,l,c,d,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="eventemitter-buffers-and-streams-—-practice" tabindex="-1">EventEmitter, Buffers, and Streams — practice <a class="header-anchor" href="#eventemitter-buffers-and-streams-—-practice" aria-label="Permalink to “EventEmitter, Buffers, and Streams — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These tasks were separated from the textbook; no completion is credited.</p><p><a href="./../../node-js/module-03-events-buffers-streams.html">Textbook explanation</a> · <a href="./">Node.js practice map</a></p><h3 id="diagnostic-exercise" tabindex="-1"><span class="hub-section-number">1 </span>Diagnostic exercise <a class="header-anchor" href="#diagnostic-exercise" aria-label="Permalink to “1 Diagnostic exercise”">​</a></h3><p>Process a large newline-delimited file with bounded memory.</p><p>Requirements:</p><ul><li>reject a record larger than 1 MB;</li><li>preserve multibyte UTF-8 characters across chunks;</li><li>report the line number for malformed JSON;</li><li>stop the whole pipeline when output fails;</li><li>support cancellation;</li><li>demonstrate that a slow destination does not cause unbounded memory growth.</li></ul><hr><h2 id="_15-final-review-checklist" tabindex="-1"><span class="hub-section-number">2 </span>Final review checklist <a class="header-anchor" href="#_15-final-review-checklist" aria-label="Permalink to “2 Final review checklist”">​</a></h2><p>You should be able to explain and demonstrate each point:</p><h3 id="framing-and-diagnosis" tabindex="-1"><span class="hub-section-number">2.1 </span>Framing and diagnosis <a class="header-anchor" href="#framing-and-diagnosis" aria-label="Permalink to “2.1 Framing and diagnosis”">​</a></h3><ul><li>Treat stream chunks as arbitrary boundaries, not application messages.</li><li>Preserve multibyte text across chunks.</li><li>Bound every delimiter- or length-based frame.</li><li>Diagnose ignored backpressure, unfinished callbacks, missing end signals, and partial output.</li><li>Use <code>pipeline()</code> as one error, cleanup, completion, and cancellation boundary.</li></ul><h3 id="eventemitter" tabindex="-1"><span class="hub-section-number">2.2 </span>EventEmitter <a class="header-anchor" href="#eventemitter" aria-label="Permalink to “2.2 EventEmitter”">​</a></h3><ul><li><code>on()</code> registers a persistent listener; <code>once()</code> registers a one-use listener.</li><li><code>emit()</code> calls listeners synchronously in registration order.</li><li>The listener must be registered on the same emitter instance before the event occurs.</li><li>A listener added after an event does not receive that past event.</li><li>An unhandled <code>&#39;error&#39;</code> event throws.</li><li>A listener&#39;s thrown exception is not automatically converted to an <code>&#39;error&#39;</code> event.</li><li><code>emit()</code> does not await async listeners or propagate their rejections as promise results.</li><li><code>off()</code> needs the same listener function reference used by <code>on()</code>.</li><li>Listener-count warnings usually indicate missing lifecycle cleanup.</li><li>Events suit repeated fan-out notifications; promises suit one result or error.</li></ul><h3 id="buffer" tabindex="-1"><span class="hub-section-number">2.3 </span>Buffer <a class="header-anchor" href="#buffer" aria-label="Permalink to “2.3 Buffer”">​</a></h3><ul><li>A buffer is a fixed-length byte sequence used for binary data.</li><li><code>Buffer.from()</code> converts existing data; <code>Buffer.alloc()</code> creates initialized storage.</li><li><code>Buffer.allocUnsafe()</code> can expose stale memory unless every byte is overwritten.</li><li>UTF-8 string length and byte length can differ.</li><li>Base64 and hex are encodings, not encryption.</li><li><code>toString()</code> decodes bytes using an encoding.</li><li>Numeric reads/writes must use the correct offset, size, signedness, and endianness.</li><li><code>Buffer.from(buffer)</code> copies, while <code>subarray()</code> and <code>Buffer.slice()</code> share memory.</li><li>Stream chunks may split characters, lines, and application records.</li><li>Repeated concatenation can cause unnecessary allocations and copying.</li></ul><h3 id="streams" tabindex="-1"><span class="hub-section-number">2.4 </span>Streams <a class="header-anchor" href="#streams" aria-label="Permalink to “2.4 Streams”">​</a></h3><ul><li>A readable produces data; a writable consumes it.</li><li>A duplex has independent readable and writable sides.</li><li>A transform converts writable input into readable output.</li><li>Streams extend <code>EventEmitter</code> and emit lifecycle and error events.</li><li>Readable completion uses <code>&#39;end&#39;</code>; writable completion uses <code>&#39;finish&#39;</code>; resource closure uses <code>&#39;close&#39;</code>.</li><li>Async iteration is a clean, backpressure-aware way to consume a readable.</li><li>Avoid mixing flowing, paused, piped, and async-iterator consumption styles.</li><li>Chunks have arbitrary boundaries.</li><li><code>.write()</code> returning <code>false</code> means wait for <code>&#39;drain&#39;</code>; it does not mean the write failed.</li><li><code>pipeline()</code> coordinates backpressure, failure propagation, destruction, and completion.</li><li>Application code must still clean up partial domain artifacts after pipeline failure.</li><li><code>highWaterMark</code> is a threshold, not a universal memory limit.</li><li>Object-mode thresholds count objects, regardless of each object&#39;s size.</li><li>Connected stages must agree about whether chunks are bytes/strings or objects.</li><li>Custom stream callbacks must be called exactly once.</li><li>Custom readables stop pushing when <code>push()</code> returns <code>false</code> and end with <code>push(null)</code>.</li><li>Custom transforms preserve incomplete records between chunks and flush remaining state.</li><li>Streams do not make CPU-heavy JavaScript non-blocking.</li><li>Open streams and underlying resources must be closed or destroyed on every lifecycle path.</li></ul><h3 id="failure-driven-practice-acceptance" tabindex="-1"><span class="hub-section-number">2.5 </span>Failure-driven practice acceptance <a class="header-anchor" href="#failure-driven-practice-acceptance" aria-label="Permalink to “2.5 Failure-driven practice acceptance”">​</a></h3><p>Baseline: Node24.18.0. Run the JSONL stage through pipeline with a compatible bounded byte source and a slow object-mode writable (highWaterMark1). Feed split UTF-8, split CRLF, multiple records in one chunk, final record without LF, whitespace, malformed JSON with line number, invalid UTF-8, null followed by an object, arrays/primitives, excessive frame/chunk/count and empty input.</p><p>Acceptance: valid objects survive exactly once; invalid input rejects the pipeline; source/destination are destroyed on failure; no push-after-EOF; parsing pauses with downstream demand rather than preproducing all records. Abort a blocked pipeline and fail the destination; verify generator/source cleanup. Observe bounded queue/pull counts and a realistic memory trend separately; a tiny fixture does not prove constant RSS.</p><p>For countErrorLines, test a missing file and an input that errors after a valid line; both must reject and release the input. On normal EOF require the expected count and resource closure. For UppercaseTransform, decoded strings succeed and Buffer input fails through the callback. Compare finished listener counts with cleanup:true on an owned stream. Exercise Job task/listener failure contracts and abort an events.on loop, checking listeners return to their initial count.</p><p>Run the delegated iterator break and explicit return cases and retain cleanup evidence. Run the serialization table, then serializeProgress with unknown/invalid/cyclic-extra/BigInt-required/secret-extra inputs and require the documented projection/errors. Learner exercises and service-scale memory/platform validation remain required even when example checks pass.</p><p>References checked2026-10-21: <a href="https://nodejs.org/download/release/v24.18.0/docs/api/stream.html" target="_blank" rel="noreferrer">Node24 streams</a>, <a href="https://nodejs.org/download/release/v24.18.0/docs/api/readline.html" target="_blank" rel="noreferrer">Node24 readline</a>, <a href="https://nodejs.org/download/release/v24.18.0/docs/api/events.html" target="_blank" rel="noreferrer">Node24 events</a>, <a href="https://tc39.es/ecma262/multipage/control-abstraction-objects.html" target="_blank" rel="noreferrer">ECMAScript iteration</a>, <a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-json-object" target="_blank" rel="noreferrer">JSON algorithms</a>.</p>',24)])])}const m=a(n,[["render",s]]);export{h as __pageData,m as default};
